sni/codes.py:
"""Codes (spec §2 ``code``; §4 step 1): dense prototypes or sparse expanded k-WTA codes (H-03)."""

from __future__ import annotations

import numpy as np


class Code:
    """``code ∈ {dense, sparse}``. Sparse: fixed seeded random expansion to D = expansion·d,
    then k-winners-take-all → a binary code scaled to unit norm (FlyHash-style). Dense: identity."""

    def __init__(self, kind: str, dim: int, *, expansion: int = 8, fraction: float = 0.05,
                 seed: int = 0) -> None:  # fmt: skip
        if kind not in ("dense", "sparse"):
            raise ValueError(f"code={kind!r}")
        self.kind, self.in_dim = kind, dim
        if kind == "sparse":
            rng = np.random.default_rng(np.random.SeedSequence([seed, 0xC0DE]))
            self.D = dim * int(expansion)
            self.k = max(1, int(round(fraction * self.D)))
            self.M = rng.normal(size=(self.D, dim))
            self.dim = self.D
        else:
            self.dim = dim

    def __call__(self, z: np.ndarray) -> np.ndarray:
        if self.kind == "dense":
            return np.asarray(z, dtype=float)
        h = self.M @ z
        out = np.zeros(self.D)
        out[np.argpartition(h, -self.k)[-self.k :]] = 1.0 / np.sqrt(self.k)  # unit norm
        return out

    def similarity(self, c: np.ndarray, stored: np.ndarray) -> np.ndarray:
        """Overlap of a code with stored codes in [−1, 1] (cosine; for binary k-WTA codes this
        is the fraction of shared active bits)."""
        if stored.shape[0] == 0:
            return np.zeros(0)
        num = stored @ c
        den = np.linalg.norm(stored, axis=1) * (np.linalg.norm(c) + 1e-12) + 1e-12
        return num / den

sni/consolidation.py:
"""Consolidation (spec §5; switch ``consolidation ∈ {write, offline, both, none}``).

* write-time (ART-style): a confirmed naming of input x merges into the winning prototype if it
  lies within vigilance *and* the winner already names the same word (match tracking); else a
  new provisional unit is formed. Decided by :func:`write_time_target`.
* offline pass (:func:`offline_pass`), gated by predictability: merge, split, downscale, prune.
  A merge needs the pooled exemplars to be predicted by the pair (``merge_predictability``); a
  split needs a contradicted unit whose exemplars form two modes novel to each other.
  Every change it makes to a learned quantity is a *replay* through the same audited update
  functions (L5: each replay update satisfies L1–L4): a merge replays the absorbed unit's stored
  exemplars into the survivor; a split replays one mode's exemplars into a new unit; downscaling
  is ``update_downscale``. Consolidated items are never pruned.

Episodic store: traces are never edited; the offline pass instead forms level-2 *concept*
prototypes by replaying the traces that share a confirmed name (episodic → concept prototypes).
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any

import numpy as np

from sni.plasticity import update_downscale, update_edge_named, update_prototype_stats

if TYPE_CHECKING:  # pragma: no cover
    from sni.engine import Brain


def write_time_target(brain: Brain, code: np.ndarray, word_unit: int, relation: str) -> int:
    """The unit a confirmed naming merges into, or -1 for "form a new unit"."""
    cfg = brain.cfg
    if cfg.store != "prototype" or cfg.consolidation not in ("write", "both"):
        return -1
    m = brain.match_code(code)
    if m.profile.best < 0 or m.profile.eps0 > cfg.engine.vigilance:
        return -1
    best = m.profile.best
    if brain.answer_of(best, relation) not in (word_unit, -1):
        return -1  # match tracking: the winner names something else → new unit
    return best


def _named_answer(brain: Brain, unit: int) -> int:
    return brain.answer_of(unit, "named") if "named" in brain.edges.types else -1


def _replay_into(brain: Brain, target: int, codes: list[np.ndarray]) -> None:
    """Replay stored exemplars into ``target`` with the replay modulator m = +1 (the stored,
    already-confirmed verdict); each replay is one local prototype update."""
    eta = brain.cfg.params.eta_phi
    for x in codes:
        delta = update_prototype_stats(
            np.asarray(x), brain.units.theta_stats(target)[0], 1.0, eta=eta
        )
        brain.units.commit_stats(target, delta[None])


def offline_pass(brain: Brain) -> dict[str, Any]:
    cfg, p, units, edges = brain.cfg, brain.cfg.engine, brain.units, brain.edges
    stats = {"merged": 0, "split": 0, "concepts": 0, "downscaled": 0, "pruned_edges": 0,
             "pruned_units": 0}  # fmt: skip
    percepts = [int(i) for i in units.ids("percept")]

    if cfg.store == "prototype":
        # (a) gated merge of provisional pairs that name the same word
        for a in percepts:
            if not units.meta[a].alive or units.meta[a].consolidated:
                continue
            for b in percepts:
                if b <= a or not units.meta[b].alive or units.meta[b].consolidated:
                    continue
                wa, wb = _named_answer(brain, a), _named_answer(brain, b)
                if wa < 0 or wa != wb:
                    continue
                va, vb = units.var[a] + units.var_floor, units.var[b] + units.var_floor
                d2 = (units.phi[a] - units.phi[b]) ** 2
                if np.mean(d2 / va) > p.vigilance or np.mean(d2 / vb) > p.vigilance:
                    continue
                pool = units.meta[a].exemplars + units.meta[b].exemplars
                if not pool or _predictability(brain, pool, {a, b}) < p.merge_predictability:
                    continue  # unpredictable items stay separate (Go-CLS gate)
                _replay_into(brain, a, [np.asarray(x) for x in units.meta[b].exemplars])
                units.meta[a].exemplars = (units.meta[a].exemplars + units.meta[b].exemplars)[
                    : units.reservoir
                ]
                _kill_unit(brain, b)
                stats["merged"] += 1
        # split bimodal units (replay one mode into a new unit)
        for a in [int(i) for i in units.ids("percept")]:
            ex = units.meta[a].exemplars
            # gate: only a unit whose predictions were contradicted is a split candidate
            if units.meta[a].consolidated or units.meta[a].contra <= 0 or len(ex) < 4:
                continue
            X = np.asarray(ex)
            lab = _two_means(X)
            if lab is None:
                continue
            c0, c1 = X[lab == 0].mean(0), X[lab == 1].mean(0)
            if np.mean((c0 - c1) ** 2 / (units.var[a] + units.var_floor)) <= p.theta_novel:
                continue  # the two modes would not be novel to each other: no split
            word = _named_answer(brain, a)
            new = units.add("percept", X[lab == 1][0], t=brain.t)
            _replay_into(brain, new, list(X[lab == 1][1:]))
            units.meta[new].exemplars = [list(x) for x in X[lab == 1]]
            units.meta[a].exemplars = [list(x) for x in X[lab == 0]]
            if word >= 0:
                e = edges.add(new, "named", word, t=brain.t)
                edges.commit_w(
                    e, update_edge_named(1.0, True, eta=float(edges.w[edges.get(a, "named", word)]))
                )
            stats["split"] += 1
    elif cfg.store == "episodic" and "named" in edges.types:
        groups: dict[int, list[int]] = {}
        for a in percepts:
            w = _named_answer(brain, a)
            if w >= 0:
                groups.setdefault(w, []).append(a)
        have = {_named_answer(brain, c) for c in units.ids("concept")}
        for word, members in sorted(groups.items()):
            if word in have or len(members) < 2:
                continue
            codes = [units.phi[i] for i in members]
            sims = [
                float(np.dot(x, codes[0]) / (np.linalg.norm(x) * np.linalg.norm(codes[0]) + 1e-12))
                for x in codes[1:]
            ]
            if np.mean(sims) < 1.0 - p.vigilance / p.retrieval_beta:
                continue  # predictability gate: the traces do not cluster
            c = units.add("concept", codes[0], t=brain.t, level=2)
            _replay_into(brain, c, codes[1:])
            e = edges.add(c, "named", word, t=brain.t)
            edges.commit_w(e, update_edge_named(1.0, True, eta=brain.cfg.params.eta))
            stats["concepts"] += 1

    # (b) downscale provisional edges, (c) prune weak unsupported ones and weak units
    live = [int(i) for i in edges.live() if not edges.meta[i].consolidated]
    if live:
        edges.commit_w(live, update_downscale(edges.w[live], rho=p.downscale))
        stats["downscaled"] = len(live)
    for i in live:
        if edges.w[i] < p.prune_w and not any(v > 0 for v in edges.meta[i].support.values()):
            edges.kill(i)
            stats["pruned_edges"] += 1
    for a in [int(i) for i in units.ids("percept")] + [int(i) for i in units.ids("concept")]:
        m = units.meta[a]
        if not m.consolidated and units.s[a] < p.s_min:
            _kill_unit(brain, a)
            stats["pruned_units"] += 1
    return stats


def _kill_unit(brain: Brain, unit: int) -> None:
    brain.units.kill(unit)
    for r in brain.edges.types:
        for e in brain.edges.outgoing(unit, r):
            brain.edges.kill(e)


def _predictability(brain: Brain, pool: list[list[float]], members: set[int]) -> float:
    """Share of the pooled exemplars whose best-matching unit is one of ``members``."""
    hits = 0
    for x in pool:
        m = brain.match_code(np.asarray(x))
        hits += int(m.profile.best in members)
    return hits / len(pool)


def _two_means(X: np.ndarray, iters: int = 10) -> np.ndarray | None:
    i0 = 0
    i1 = int(np.argmax(np.sum((X - X[0]) ** 2, axis=1)))
    if i1 == i0:
        return None
    c = np.stack([X[i0], X[i1]])
    lab = np.zeros(len(X), dtype=int)
    for _ in range(iters):
        lab = np.argmin(((X[:, None, :] - c[None]) ** 2).sum(-1), axis=1)
        if lab.min() == lab.max():
            return None
        c = np.stack([X[lab == 0].mean(0), X[lab == 1].mean(0)])
    return lab if min((lab == 0).sum(), (lab == 1).sum()) >= 2 else None

sni/engrams.py:
"""Engram store: units and typed edges (spec §3).

Every *learned* array here (prototype φ and variance, strength s, edge weight w, eligibility e,
the BCM threshold) is kept read-only. The only way to change one is ``commit_*(idx, delta)``,
and the engine computes every ``delta`` with a registered, audited update function
(``sni.plasticity``). So a write that bypasses the Locality Rule raises instead of passing
silently (tested in ``tests/test_engrams.py``).

Structural bookkeeping (creating a unit or edge, flags such as maturity or lesioned, support
ledgers, provenance, the exemplar reservoir) is not a learned quantity in the sense of L1–L5:
it records events, it does not compute with another unit's parameters.
"""

from __future__ import annotations

from contextlib import contextmanager
from dataclasses import dataclass, field
from typing import Any, Iterator

import numpy as np

KINDS = ("percept", "word", "concept")


@contextmanager
def _writable(*arrays: np.ndarray) -> Iterator[None]:
    for a in arrays:
        a.flags.writeable = True
    try:
        yield
    finally:
        for a in arrays:
            a.flags.writeable = False


def _grow(a: np.ndarray, n: int) -> np.ndarray:
    out = np.zeros((n,) + a.shape[1:], dtype=a.dtype)
    out[: a.shape[0]] = a
    out.flags.writeable = False
    return out


@dataclass
class UnitMeta:
    kind: str
    level: int
    label: str | None = None  # word units: the word; others: None
    consolidated: bool = False
    alive: bool = True
    n_fires: int = 0
    last_novelty: float = 0.0
    recency: int = 0
    created: int = 0
    support: dict[str, float] = field(default_factory=dict)
    contra: float = 0.0
    exemplars: list[list[float]] = field(default_factory=list)
    provenance: list[tuple[int, str, int, float]] = field(default_factory=list)


class UnitStore:
    """N units over a ``dim``-wide feature/code space. Word units have φ = 0 (they are matched by
    label, not by features) and never enter percept matching."""

    def __init__(self, dim: int, reservoir: int = 4, var0: float = 0.02, s0: float = 0.5,
                 var_floor: float = 0.0) -> None:  # fmt: skip
        self.dim, self.reservoir, self.var0, self.s0 = int(dim), int(reservoir), var0, s0
        self.var_floor = float(var_floor)
        self.n = 0
        cap = 16
        self.phi = _grow(np.zeros((0, self.dim)), cap)
        self.var = _grow(np.zeros((0, self.dim)), cap)
        self.s = _grow(np.zeros(0), cap)
        self.bcm = _grow(np.zeros(0), cap)  # sliding BCM threshold per unit (post side)
        self.meta: list[UnitMeta] = []
        self.words: dict[str, int] = {}

    # --- structure --------------------------------------------------------------------------
    def _ensure(self, n: int) -> None:
        cap = self.phi.shape[0]
        if n <= cap:
            return
        new = max(n, 2 * cap)
        self.phi, self.var = _grow(self.phi, new), _grow(self.var, new)
        self.s, self.bcm = _grow(self.s, new), _grow(self.bcm, new)

    def add(
        self,
        kind: str,
        phi: np.ndarray | None,
        *,
        t: int = 0,
        level: int = 1,
        label: str | None = None,
    ) -> int:
        if kind not in KINDS:
            raise ValueError(f"unknown unit kind {kind!r}")
        i = self.n
        self._ensure(i + 1)
        with _writable(self.phi, self.var, self.s):
            self.phi[i] = 0.0 if phi is None else np.asarray(phi, dtype=float)
            self.var[i] = self.var0
            self.s[i] = self.s0
        self.meta.append(UnitMeta(kind=kind, level=level, label=label, created=t, recency=t))
        self.n += 1
        if kind == "word":
            if label is None or label in self.words:
                raise ValueError(f"word units need a new label, got {label!r}")
            self.words[label] = i
        return i

    def word(self, label: str, *, t: int = 0) -> int:
        """The unit of a heard word; a new token gets a new word unit (a symbol node)."""
        if label not in self.words:
            return self.add("word", None, t=t, label=label)
        return self.words[label]

    def ids(self, kind: str | None = None, *, level: int | None = None) -> np.ndarray:
        return np.array(
            [
                i
                for i, m in enumerate(self.meta)
                if m.alive
                and (kind is None or m.kind == kind)
                and (level is None or m.level == level)
            ],
            dtype=int,
        )

    def remember(self, i: int, x: np.ndarray, rng: np.random.Generator) -> None:
        """Reservoir sampling of raw exemplars (bytes counted; used by offline gates/render)."""
        m = self.meta[i]
        m.n_fires += 1
        if len(m.exemplars) < self.reservoir:
            m.exemplars.append([float(v) for v in x])
        else:
            j = int(rng.integers(m.n_fires))
            if j < self.reservoir:
                m.exemplars[j] = [float(v) for v in x]

    def kill(self, i: int) -> None:
        self.meta[i].alive = False

    # --- learned quantities: only through update-function deltas ----------------------------
    def commit_stats(self, idx: Any, delta: np.ndarray) -> None:
        """φ, var ← (φ, var) + Δ, Δ from ``update_prototype_stats`` / ``update_unit_episodic``."""
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        delta = np.asarray(delta).reshape(len(idx), 2, self.dim)
        with _writable(self.phi, self.var):
            self.phi[idx] += delta[:, 0]
            self.var[idx] = np.maximum(self.var[idx] + delta[:, 1], 0.0)

    def commit_strength(self, idx: Any, delta: Any) -> None:
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        with _writable(self.s):
            self.s[idx] = np.clip(self.s[idx] + np.asarray(delta), 0.0, 1.0)

    def commit_bcm(self, idx: Any, delta: Any) -> None:
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        with _writable(self.bcm):
            self.bcm[idx] += np.asarray(delta)

    def theta_stats(self, idx: Any) -> np.ndarray:
        """θ for the prototype update: stacked (φ, var), shape (len(idx), 2, dim)."""
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        return np.stack([self.phi[idx], self.var[idx]], axis=1)

    def nbytes(self, *, include_reservoir: bool = True) -> int:
        """Bytes of live units: φ + var (+ reservoir), float64."""
        live = [m for m in self.meta if m.alive and m.kind != "word"]
        total = len(live) * 2 * self.dim * 8 + len(self.ids()) * 2 * 8
        if include_reservoir:
            total += sum(
                len(m.exemplars) * (len(m.exemplars[0]) if m.exemplars else 0) * 8 for m in live
            )
        return total


@dataclass
class EdgeMeta:
    consolidated: bool = False
    lesioned: bool = False
    alive: bool = True
    support: dict[str, float] = field(default_factory=dict)  # teacher -> reliability-weighted +
    contra: float = 0.0
    created: int = 0
    provenance: list[tuple[int, str, int, float]] = field(default_factory=list)


class EdgeStore:
    """Typed, weighted, lesionable edges. Types come from the task's query frames (not learned)."""

    def __init__(self, types: tuple[str, ...]) -> None:
        if len(set(types)) != len(types) or not types:
            raise ValueError("relation types must be a non-empty set")
        self.types = tuple(types)
        self.n = 0
        cap = 32
        self.src = np.zeros(cap, dtype=int)
        self.dst = np.zeros(cap, dtype=int)
        self.rtype = np.zeros(cap, dtype=int)
        self.w = _grow(np.zeros(0), cap)
        self.e = _grow(np.zeros(0), cap)
        self.meta: list[EdgeMeta] = []
        self.index: dict[tuple[int, int, int], int] = {}
        self.out: dict[tuple[int, int], list[int]] = {}
        self.into: dict[tuple[int, int], list[int]] = {}

    def type_id(self, r: str) -> int:
        try:
            return self.types.index(r)
        except ValueError as exc:
            raise ValueError(f"unknown relation type {r!r}; known {self.types}") from exc

    def _ensure(self, n: int) -> None:
        cap = self.src.shape[0]
        if n <= cap:
            return
        new = max(n, 2 * cap)
        for name in ("src", "dst", "rtype"):
            a = getattr(self, name)
            b = np.zeros(new, dtype=int)
            b[: a.shape[0]] = a
            setattr(self, name, b)
        self.w, self.e = _grow(self.w, new), _grow(self.e, new)

    def get(self, src: int, r: str, dst: int) -> int | None:
        return self.index.get((int(src), self.type_id(r), int(dst)))

    def add(self, src: int, r: str, dst: int, *, t: int = 0) -> int:
        """A new provisional edge at w = 0 (its weight then comes only from update deltas)."""
        key = (int(src), self.type_id(r), int(dst))
        if key in self.index:
            idx = self.index[key]
            self.meta[idx].alive = True
            return idx
        idx = self.n
        self._ensure(idx + 1)
        self.src[idx], self.rtype[idx], self.dst[idx] = key
        self.meta.append(EdgeMeta(created=t))
        self.index[key] = idx
        self.out.setdefault((key[0], key[1]), []).append(idx)
        self.into.setdefault((key[2], key[1]), []).append(idx)
        self.n += 1
        return idx

    def outgoing(self, src: int, r: str, *, live_only: bool = True) -> list[int]:
        idx = self.out.get((int(src), self.type_id(r)), [])
        return [i for i in idx if self.meta[i].alive] if live_only else list(idx)

    def incoming(self, dst: int, r: str) -> list[int]:
        return [i for i in self.into.get((int(dst), self.type_id(r)), []) if self.meta[i].alive]

    def live(self) -> np.ndarray:
        return np.array([i for i in range(self.n) if self.meta[i].alive], dtype=int)

    def of_type(self, r: str) -> np.ndarray:
        rid = self.type_id(r)
        return np.array(
            [i for i in range(self.n) if self.meta[i].alive and self.rtype[i] == rid], dtype=int
        )

    def commit_w(self, idx: Any, delta: Any) -> None:
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        with _writable(self.w):
            np.add.at(self.w, idx, np.asarray(delta, dtype=float) * np.ones(len(idx)))
            self.w[idx] = np.clip(self.w[idx], 0.0, 1.0)

    def commit_e(self, idx: Any, delta: Any) -> None:
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        with _writable(self.e):
            self.e[idx] += np.asarray(delta, dtype=float) * np.ones(len(idx))

    def kill(self, idx: int) -> None:
        self.meta[idx].alive = False

    def nbytes(self) -> int:
        return len(self.live()) * (2 * 8 + 3 * 8)  # w, e (+ src, dst, type)

sni/locality_audit.py:
"""Locality audit: enforcement of the SNI Locality Rule (L1-L5) on every update function.

The rule (Lead Synthesis 02 §3): every change to a learned quantity is
    Δθ = F(u_pre, u_post, θ, e_θ, m_t)
plus, as the single declared exception (L3), a binary selection ``tag``. This module checks it
in two layers, and CI fails if either fails (``python -m sni.locality_audit`` exits non-zero):

STATIC  (AST of the function source)
  * positional parameters are drawn from ALLOWED_ARGS (+ ``tag``); everything else must be a
    keyword-only *hyper-parameter* with a numeric/bool default (a constant, not data);
  * every parameter is annotated (float / int / bool / np.ndarray);
  * the body touches no free name except an allow-listed builtin, ``np``/``math`` attributes from
    an allow-list, or another registered update function (so: no module globals, no ``self``,
    no ``open``/``getattr``/``globals``, no ``np.random``, no imports, no ``global``);
  * attribute access on a parameter is limited to array-shape/reduction attributes, so a
    parameter cannot be used to reach another object;
  * every top-level ``update_*`` function in an audited module is registered.

RUNTIME  (black-box, on probes generated from the signature)
  * determinism, also under a reseeded global RNG, and the global RNG state is not consumed;
  * inputs are not mutated and module globals are not mutated;
  * output does not depend on module-level data (all numeric/array globals are scrambled);
  * shuffled-input test: a batch of B independent instances is evaluated; permuting the
    instances permutes the output identically, and replacing instance j leaves every other
    output bit-identical (zero cross-talk, i.e. no dependence on anything outside the allowed
    inputs of that instance).

Inference (settling, spreading, NNLS) is not learning and is not audited here (rule, last
paragraph); only functions that write a learned quantity are registered.
"""

from __future__ import annotations

import ast
import builtins
import copy
import importlib
import inspect
import sys
import textwrap
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable

import numpy as np

ALLOWED_ARGS: tuple[str, ...] = ("u_pre", "u_post", "theta", "e_theta", "m_t")
TAG_ARG = "tag"  # L3: binary selection tag, no magnitude
ALLOWED_POSITIONAL = ALLOWED_ARGS + (TAG_ARG,)

_ALLOWED_BUILTINS = {"float", "int", "bool", "abs", "min", "max"}
_ALLOWED_NP_ATTRS = {
    "abs", "asarray", "clip", "exp", "float64", "log", "maximum", "minimum", "ndarray",
    "ones_like", "sqrt", "stack", "sum", "where", "zeros_like",
}  # fmt: skip
_ALLOWED_MATH_ATTRS = {"exp", "log", "sqrt"}
_ALLOWED_PARAM_ATTRS = {"shape", "size", "ndim", "dtype", "T", "sum", "copy", "astype"}
_ALLOWED_ANNOTATIONS = {"float", "int", "bool", "ndarray", "np.ndarray"}

# modules whose update functions CI audits; extend as the build order adds mechanisms
AUDITED_MODULES: tuple[str, ...] = ("sni.plasticity", "sni.perception")


class LocalityViolation(AssertionError):  # noqa: N818
    """Raised by :func:`assert_local` when an update function breaks the rule."""


@dataclass(frozen=True)
class UpdateSpec:
    name: str
    fn: Callable[..., Any]
    core_shapes: dict[str, tuple[int, ...]]


REGISTRY: dict[str, UpdateSpec] = {}


def update_function(
    fn: Callable[..., Any] | None = None, *, core_shapes: dict[str, tuple[int, ...]] | None = None
) -> Any:
    """Register ``fn`` as a learned-quantity update. ``core_shapes`` gives the per-instance shape
    of array arguments for the probes (default: scalar for float/int/bool, ``(4,)`` for ndarray).
    """

    def register(f: Callable[..., Any]) -> Callable[..., Any]:
        if f.__name__ in REGISTRY and REGISTRY[f.__name__].fn is not f:
            raise ValueError(f"duplicate update function name {f.__name__!r}")
        REGISTRY[f.__name__] = UpdateSpec(f.__name__, f, dict(core_shapes or {}))
        return f

    return register if fn is None else register(fn)


# --------------------------------------------------------------------------------------------
# static layer
# --------------------------------------------------------------------------------------------
def _annotation_name(ann: Any) -> str:
    if ann is inspect.Parameter.empty:
        return ""
    if isinstance(ann, str):
        return ann.replace(" ", "")
    return getattr(ann, "__name__", str(ann))


def _function_ast(fn: Callable[..., Any]) -> ast.FunctionDef:
    src = textwrap.dedent(inspect.getsource(fn))
    tree = ast.parse(src)
    node = tree.body[0]
    if not isinstance(node, ast.FunctionDef):
        raise LocalityViolation(f"{fn!r} is not a plain function")
    return node


def static_violations(fn: Callable[..., Any]) -> list[str]:
    """Return the static violations of ``fn`` (empty list = clean)."""
    out: list[str] = []
    name = fn.__name__
    sig = inspect.signature(fn)

    kw_only = {p.name for p in sig.parameters.values() if p.kind is p.KEYWORD_ONLY}
    for p in sig.parameters.values():
        if p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD):
            out.append(f"{name}: *args/**kwargs hide inputs from the audit ({p.name})")
            continue
        if _annotation_name(p.annotation) not in _ALLOWED_ANNOTATIONS:
            out.append(
                f"{name}: parameter {p.name!r} needs an annotation in {_ALLOWED_ANNOTATIONS}"
            )
        if p.name in kw_only:
            if p.default is p.empty or not isinstance(p.default, (int, float, bool)):
                out.append(f"{name}: hyper-parameter {p.name!r} needs a numeric/bool default")
            if p.name in ALLOWED_POSITIONAL:
                out.append(f"{name}: {p.name!r} must be positional, not a hyper-parameter")
        elif p.name not in ALLOWED_POSITIONAL:
            out.append(
                f"{name}: argument {p.name!r} is not in the Locality Rule set "
                f"{ALLOWED_POSITIONAL}; pass constants as keyword-only hyper-parameters"
            )
        if p.name == TAG_ARG and _annotation_name(p.annotation) != "bool":
            out.append(f"{name}: the selection tag must be bool (no magnitude)")

    try:
        node = _function_ast(fn)
    except (OSError, TypeError, SyntaxError) as exc:  # pragma: no cover - source unavailable
        return out + [f"{name}: cannot read source for the audit ({exc})"]

    params = {p.name for p in sig.parameters.values()}
    local: set[str] = set(params)
    loads: set[str] = set()
    # only the body is audited: decorators and annotations are not executed as part of Δθ
    body_nodes = [sub for stmt in node.body for sub in ast.walk(stmt)]
    for sub in body_nodes:
        if isinstance(sub, ast.Name):
            (local if isinstance(sub.ctx, ast.Store) else loads).add(sub.id)
        elif isinstance(sub, (ast.Global, ast.Nonlocal)):
            out.append(f"{name}: global/nonlocal statements are forbidden")
        elif isinstance(sub, (ast.Import, ast.ImportFrom)):
            out.append(f"{name}: imports inside an update function are forbidden")
        elif isinstance(sub, ast.arg):
            local.add(sub.arg)

    allowed_names = _ALLOWED_BUILTINS | {"np", "math"} | set(REGISTRY)
    for free in sorted(loads - local):
        if free not in allowed_names:
            hint = "builtin" if hasattr(builtins, free) else "module-level name"
            out.append(f"{name}: reads forbidden {hint} {free!r}")

    for sub in body_nodes:
        if not isinstance(sub, ast.Attribute) or not isinstance(sub.value, ast.Name):
            continue
        base, attr = sub.value.id, sub.attr
        if base == "np" and attr not in _ALLOWED_NP_ATTRS:
            out.append(f"{name}: np.{attr} is not on the audit allow-list")
        elif base == "math" and attr not in _ALLOWED_MATH_ATTRS:
            out.append(f"{name}: math.{attr} is not on the audit allow-list")
        elif base in params and attr not in _ALLOWED_PARAM_ATTRS:
            out.append(f"{name}: attribute {base}.{attr} may reach another object")
    return out


def module_registration_violations(module_name: str) -> list[str]:
    """Every top-level ``update_*`` function of the module must be decorated and registered."""
    module = importlib.import_module(module_name)
    src_file = inspect.getsourcefile(module)
    if src_file is None:  # pragma: no cover
        return [f"{module_name}: no source file"]
    tree = ast.parse(Path(src_file).read_text())
    out: list[str] = []
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name.startswith("update_"):
            decorated = any(
                (isinstance(d, ast.Name) and d.id == "update_function")
                or (
                    isinstance(d, ast.Call)
                    and isinstance(d.func, ast.Name)
                    and d.func.id == "update_function"
                )
                for d in node.decorator_list
            )
            if not decorated or node.name not in REGISTRY:
                out.append(f"{module_name}.{node.name}: update function is not registered/audited")
    return out


# --------------------------------------------------------------------------------------------
# runtime layer
# --------------------------------------------------------------------------------------------
_BATCH = 6
_ARRAY_LEN = 4


def _kind(p: inspect.Parameter) -> str:
    name = _annotation_name(p.annotation)
    return "array" if "ndarray" in name else ("bool" if name == "bool" else "scalar")


def _draw(rng: np.random.Generator, pname: str, kind: str, shape: tuple[int, ...]) -> Any:
    if kind == "bool":
        return rng.random(shape) < 0.5
    if pname == "m_t":
        return rng.normal(size=shape)
    return rng.random(shape)  # activities, weights and traces live in [0, 1]


def _instances(
    fn: Callable[..., Any], core: dict[str, tuple[int, ...]], rng: np.random.Generator, batch: int
) -> dict[str, Any]:
    args: dict[str, Any] = {}
    for p in inspect.signature(fn).parameters.values():
        if p.kind is p.KEYWORD_ONLY:
            continue
        kind = _kind(p)
        shape = core.get(p.name, (_ARRAY_LEN,) if kind == "array" else ())
        args[p.name] = _draw(rng, p.name, kind, (batch,) + shape)
    return args


def _take(args: dict[str, Any], idx: Any) -> dict[str, Any]:
    return {k: v[idx] for k, v in args.items()}


def runtime_violations(
    fn: Callable[..., Any], core_shapes: dict[str, tuple[int, ...]] | None = None, seed: int = 0
) -> list[str]:
    """Black-box checks on probes generated from the signature (see module docstring)."""
    out: list[str] = []
    name = fn.__name__
    core = dict(core_shapes or {})
    rng = np.random.default_rng(seed)
    args = _instances(fn, core, rng, _BATCH)
    base = fn(**copy.deepcopy(args))

    # determinism, with a differently seeded global RNG, and no RNG consumption
    state_before = np.random.get_state()
    np.random.seed(12345)
    again = fn(**copy.deepcopy(args))
    np.random.seed(54321)
    third = fn(**copy.deepcopy(args))
    np.random.set_state(state_before)
    if not (np.array_equal(base, again) and np.array_equal(base, third)):
        out.append(f"{name}: output depends on something other than its arguments (RNG/state)")
    probe_state = np.random.get_state()
    fn(**copy.deepcopy(args))
    after_state = np.random.get_state()
    if not all(np.array_equal(a, b) for a, b in zip(probe_state, after_state)):
        out.append(f"{name}: consumes the global RNG")

    # inputs and module globals are not mutated
    frozen = copy.deepcopy(args)
    fn(**args)
    if any(not np.array_equal(frozen[k], args[k]) for k in args):
        out.append(f"{name}: mutates its inputs")
    g = fn.__globals__
    ids = {k: id(v) for k, v in g.items()}
    fn(**copy.deepcopy(args))
    if ids != {k: id(v) for k, v in g.items()}:
        out.append(f"{name}: rebinds module globals")

    # no dependence on module-level data: scramble every data-like global, restore afterwards
    saved = {}
    for k, v in list(g.items()):
        if k.startswith("__"):
            continue
        if isinstance(v, (int, float, np.ndarray, list, dict, tuple)) and not isinstance(v, bool):
            saved[k] = v
    try:
        for k, v in saved.items():
            if isinstance(v, np.ndarray):
                g[k] = rng.normal(size=v.shape)
            elif isinstance(v, (int, float)):
                g[k] = v + 1234.5
            else:
                g[k] = None
        scrambled = fn(**copy.deepcopy(args))
    except Exception:  # noqa: BLE001 - a crash under scrambled globals is itself a dependence
        scrambled = None
    finally:
        g.update(saved)
    if scrambled is None or not np.array_equal(base, scrambled):
        out.append(f"{name}: output changes when module-level data is scrambled")

    # shuffled-input test: permutation equivariance and zero cross-talk between instances
    perm = rng.permutation(_BATCH)
    permuted = fn(**_take(copy.deepcopy(args), perm))
    if not np.array_equal(np.asarray(base)[perm], permuted):
        out.append(f"{name}: shuffling the instances does not shuffle the outputs (coupled)")
    j = int(rng.integers(_BATCH))
    other = _instances(fn, core, rng, _BATCH)
    changed = copy.deepcopy(args)
    for k in changed:
        changed[k][j] = other[k][j]
    alt = np.asarray(fn(**changed))
    mask = np.arange(_BATCH) != j
    if not np.array_equal(np.asarray(base)[mask], alt[mask]):
        out.append(f"{name}: instance j influences the output of other instances (cross-talk)")
    return out


# --------------------------------------------------------------------------------------------
# entry points
# --------------------------------------------------------------------------------------------
def audit_function(
    fn: Callable[..., Any], core_shapes: dict[str, tuple[int, ...]] | None = None
) -> list[str]:
    """All violations (static + runtime) of one function; works on unregistered functions too."""
    found = static_violations(fn)
    if not found:  # runtime probes are only meaningful for a well-formed signature
        found += runtime_violations(fn, core_shapes)
    return found


def audit_all(modules: tuple[str, ...] = AUDITED_MODULES) -> dict[str, list[str]]:
    """Audit every registered update function of the audited modules. Empty lists = clean."""
    report: dict[str, list[str]] = {}
    for module_name in modules:
        importlib.import_module(module_name)
        missing = module_registration_violations(module_name)
        if missing:
            report[module_name] = missing
    for spec in REGISTRY.values():
        report[spec.name] = audit_function(spec.fn, spec.core_shapes)
    if not REGISTRY:
        report["<registry>"] = ["no update functions registered: nothing was audited"]
    return report


def assert_local(
    fn: Callable[..., Any], core_shapes: dict[str, tuple[int, ...]] | None = None
) -> None:
    found = audit_function(fn, core_shapes)
    if found:
        raise LocalityViolation("; ".join(found))


def main() -> int:
    report = audit_all()
    bad = {k: v for k, v in report.items() if v}
    for name, problems in sorted(report.items()):
        print(("FAIL " if problems else "ok   ") + name)
        for problem in problems:
            print("     - " + problem)
    print(f"\n{len(report) - len(bad)}/{len(report)} clean")
    return 1 if bad else 0


if __name__ == "__main__":
    # Re-import under the canonical name: running with ``-m`` creates a second copy of this
    # module as ``__main__``, whose REGISTRY would stay empty because sni.plasticity registers
    # into ``sni.locality_audit``.
    from sni.locality_audit import main as _canonical_main

    sys.exit(_canonical_main())

sni/novelty.py:
"""Internal signals (spec §1.5 glossary). Three separate quantities, never aliased:

* **novelty**  ν — energy of the *static* memory model against the input
  (ν = −log Σᵢ πᵢ exp(−Eᵢ/2)); gates formation and question choice, never enters m_t;
* **surprise** γ_BF — temporal prediction error in Bayes-factor form, on the stream of outcomes;
  sets the learning rate through m_t;
* **expected uncertainty** — learned precision (1/var), stored per prototype in ``engrams``.

Plus the novelty *profile* (ε₀, ε₁, margin, ν) of spec §4 step 3 and its fixed readout.
Everything here is inference: it reads stored records, it writes nothing.
"""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np

PROFILE_CLASSES = ("known", "ambiguous", "composite", "novel")


@dataclass(frozen=True)
class Profile:
    eps0: float  # best single-unit prediction error (per dimension)
    eps1: float  # residual error after explaining-away over the top-m units (NNLS)
    margin: float  # energy gap between the best two units with different answers
    nu: float  # novelty energy of the static model
    best: int  # best unit id (-1: empty store)

    def as_vector(self) -> np.ndarray:
        return np.array([self.eps0, self.eps1, self.margin, self.nu])


EMPTY_PROFILE = Profile(np.inf, np.inf, 0.0, np.inf, -1)


def nnls(A: np.ndarray, b: np.ndarray, max_iter: int = 50) -> np.ndarray:
    """Lawson–Hanson non-negative least squares, min ‖A c − b‖ s.t. c ≥ 0 (A: d × m, m small)."""
    m = A.shape[1]
    c = np.zeros(m)
    passive = np.zeros(m, dtype=bool)
    for _ in range(max_iter):
        grad = A.T @ (b - A @ c)
        if passive.all() or grad[~passive].max(initial=-np.inf) <= 1e-10:
            break
        j = int(np.argmax(np.where(passive, -np.inf, grad)))
        passive[j] = True
        while True:
            s = np.zeros(m)
            s[passive] = np.linalg.lstsq(A[:, passive], b, rcond=None)[0]
            if (s[passive] > 0).all():
                c = s
                break
            neg = passive & (s <= 0)
            alpha = np.min(c[neg] / (c[neg] - s[neg] + 1e-15))
            c = c + alpha * (s - c)
            passive &= c > 1e-12
    return c


def novelty_energy(energy: np.ndarray, counts: np.ndarray) -> float:
    """ν = −log Σ πᵢ exp(−Eᵢ/2), πᵢ ∝ counts (static-model energy; glossary)."""
    if energy.size == 0:
        return float("inf")
    pi = (counts + 1.0) / np.sum(counts + 1.0)
    x = -energy / 2.0 + np.log(pi)
    top = np.max(x)
    return float(-(top + np.log(np.sum(np.exp(x - top)))))


def competition_margin(energy: np.ndarray, answers: list[int]) -> float:
    """E₍₂₎ − E₍₁₎ over units whose answers differ (Candidate A §3 step 5). With fewer than two
    distinct answers the margin is +inf (no competitor)."""
    order = np.argsort(energy)
    if order.size == 0:
        return 0.0
    first = answers[order[0]]
    for j in order[1:]:
        if answers[j] != first or first == -1:
            return float(energy[j] - energy[order[0]])
    return float("inf")


def classify_profile(p: Profile, *, theta_novel: float, theta_composite: float,
                     theta_margin: float) -> str:  # fmt: skip
    """Fixed readout of the profile into known / ambiguous / composite / novel.

    novel: nothing explains the input, alone or in combination; composite: no single unit does
    but a non-negative mix of known units does (a new combination of known parts); ambiguous:
    explained, but two different answers compete within the margin."""
    if p.best < 0:
        return "novel"
    if p.eps0 > theta_novel:
        return "composite" if p.eps1 <= theta_composite else "novel"
    if p.margin < theta_margin:
        return "ambiguous"
    return "known"


def bayes_factor_surprise(p_observed: float, p_prior: float, pc: float) -> float:
    """γ = m·S/(1 + m·S), S = p₀(outcome)/p_t(outcome), m = p_c/(1 − p_c) (card 08 §3d).

    γ ∈ [0, 1): ≈ 0 when the model predicted the outcome, → 1 when it was very unlikely."""
    if not 0.0 < p_observed <= 1.0 or not 0.0 < p_prior <= 1.0:
        raise ValueError("probabilities must be in (0, 1]")
    s = p_prior / p_observed
    m = pc / (1.0 - pc)
    return float(m * s / (1.0 + m * s))


def auroc(scores_pos: np.ndarray, scores_neg: np.ndarray) -> float:
    """P(score of a positive > score of a negative), ties count ½ (Mann–Whitney)."""
    pos, neg = np.asarray(scores_pos, float), np.asarray(scores_neg, float)
    if pos.size == 0 or neg.size == 0:
        raise ValueError("need positives and negatives")
    diff = pos[:, None] - neg[None, :]
    return float(np.mean((diff > 0) + 0.5 * (diff == 0)))

sni/plasticity.py:
"""Plasticity: every update to a learned quantity, with all plasticity switches (spec §2, §5).

Two kinds of function live here:

* **update functions** (``update_*``, registered with ``@update_function``): they return the
  increment Δθ (or Δe for the trace) and are expressed *only* through
  ``(u_pre, u_post, theta, e_theta, m_t)`` plus the binary selection ``tag`` and keyword-only
  numeric hyper-parameters. ``sni.locality_audit`` enforces this statically and at runtime, and
  CI fails otherwise. They are elementwise over leading batch dimensions, so the engine can
  vectorise over many synapses/units and the audit can shuffle them.
* **helpers** (everything else): the modulator m_t (a broadcast scalar, L2), the running
  baselines it needs, clipping, and :func:`select_updaters`, which maps a :class:`SNIConfig`
  onto the right update functions. Helpers write no learned quantity.

Interpretations the lead should confirm (also listed in the Phase 4 Build Report):

* Heterosynaptic normalisation takes ``theta`` = the *source unit's own* outgoing weight vector.
  These are the unit's own synapses, so this is read as local to that unit (L1).
* The BCM sliding threshold is carried in ``e_theta`` (metaplastic state travelling with θ) and
  is tracked by :func:`update_bcm_threshold` from the post unit's own activity.
* ``novelty`` never enters m_t (spec §5): it only gates formation and question choice.
"""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Any, Callable

import numpy as np

from sni.config import SNIConfig
from sni.locality_audit import update_function

# ============================================================================================
# update functions (audited)
# ============================================================================================


@update_function
def update_trace(u_pre: float, u_post: float, e_theta: float, *, tau: float = 3.0) -> float:
    """Δe for e ← e·exp(−1/τ) + u_pre·u_post (spec §4.8). τ = 0 keeps no memory: e ← u_pre·u_post.

    With ``trace_tau=0`` and ``feedback=bare`` this is the v1 rule R0 of card 03 (no trace).
    """
    decay = math.exp(-1.0 / tau) if tau > 0 else 0.0
    return e_theta * (decay - 1.0) + u_pre * u_post


@update_function
def update_edge_named(m_t: float, tag: bool, *, eta: float = 0.1) -> float:
    """feedback=named: Δw = η·m_t·1[edge ∈ path(proposition)]. ``tag`` is the L3 selection tag."""
    return eta * m_t * tag


@update_function
def update_edge_bare(e_theta: float, m_t: float, *, eta: float = 0.1) -> float:
    """feedback=bare: Δw = η·m_t·e (credit by the edge's own eligibility trace)."""
    return eta * m_t * e_theta


@update_function(core_shapes={"theta": (4,)})
def update_normalize_none(theta: np.ndarray) -> np.ndarray:
    """normalization=none."""
    return np.zeros_like(theta)


@update_function(core_shapes={"theta": (4,)})
def update_normalize_heterosynaptic(theta: np.ndarray, *, cap: float = 1.0) -> np.ndarray:
    """normalization=heterosynaptic: ``theta`` is one source unit's outgoing weights (last axis);
    if their sum exceeds ``cap`` they are scaled down together, preserving their ratios."""
    total = np.sum(theta, axis=-1, keepdims=True)
    scale = np.where(total > cap, cap / np.maximum(total, 1e-12), 1.0)
    return theta * scale - theta


@update_function
def update_bcm_threshold(u_post: float, e_theta: float, *, tau: float = 100.0) -> float:
    """Δ of the sliding BCM threshold θ_M (kept in ``e_theta``): θ_M tracks E[u_post²]."""
    return (u_post * u_post - e_theta) / tau


@update_function
def update_normalize_bcm(
    u_pre: float, u_post: float, e_theta: float, *, rate: float = 0.01
) -> float:
    """normalization=bcm: depression when the post unit is above its sliding threshold
    (``e_theta`` = θ_M); zero otherwise. Stabilising half of BCM, applied after every update."""
    return -rate * u_pre * u_post * np.maximum(u_post - e_theta, 0.0)


@update_function(core_shapes={"u_pre": (4,), "theta": (2, 4)})
def update_prototype_stats(
    u_pre: np.ndarray, theta: np.ndarray, m_t: float, *, eta: float = 0.1
) -> np.ndarray:
    """store=prototype. ``theta[..., 0, :]`` = φ, ``theta[..., 1, :]`` = per-dim variance;
    ``u_pre`` = the input x. Δφ = η·m⁺·(x − φ); Δvar = η·m⁺·((x − φ)² − var). Both are driven
    only by the unit's own mismatch with its prediction (L1)."""
    # the gain is capped at 1 so a large modulator can at most move φ onto x (no overshoot)
    gain = np.asarray(np.minimum(eta * np.maximum(m_t, 0.0), 1.0))[..., None]
    err = u_pre - theta[..., 0, :]
    return np.stack([gain * err, gain * (err * err - theta[..., 1, :])], axis=-2)


@update_function(core_shapes={"u_pre": (4,), "theta": (2, 4)})
def update_unit_episodic(u_pre: np.ndarray, theta: np.ndarray, m_t: float) -> np.ndarray:
    """store=episodic: traces are never edited, ever (spec §5)."""
    return np.zeros_like(theta)


@update_function
def update_strength(u_post: float, theta: float, m_t: float, *, rate: float = 0.1) -> float:
    """Unit strength s ∈ [0, 1]: potentiated by a positive modulator, depressed by a negative one,
    in proportion to the unit's own participation ``u_post`` (soft-bounded, so s stays in [0, 1]).
    """
    return rate * u_post * (np.maximum(m_t, 0.0) * (1.0 - theta) - np.maximum(-m_t, 0.0) * theta)


@update_function
def update_downscale(theta: float, *, rho: float = 0.05) -> float:
    """Offline downscaling of a provisional edge weight (consolidation pass, spec §5)."""
    return -rho * theta


# ============================================================================================
# helpers (write no learned quantity)
# ============================================================================================


def apply_delta(theta: Any, delta: Any, lo: float = 0.0, hi: float = 1.0) -> Any:
    """θ ← clip(θ + Δθ). Weights live in [0, 1] (spec §3)."""
    return np.clip(np.asarray(theta) + np.asarray(delta), lo, hi)


def precision_from_var(var: np.ndarray, eps: float = 1e-6) -> np.ndarray:
    """Per-dimension precision of a prototype."""
    return 1.0 / (np.asarray(var) + eps)


def log_det_precision(var: np.ndarray, eps: float = 1e-6) -> float:
    """log-det of the (diagonal) precision matrix, tracked per unit (spec §3)."""
    return float(-np.sum(np.log(np.asarray(var) + eps)))


def effective_eta(maturity: str, eta: float, eta_c: float) -> float:
    """Consolidated units/edges learn at η_c ≪ η (spec §5)."""
    if maturity not in ("provisional", "consolidated"):
        raise ValueError(f"unknown maturity {maturity!r}")
    return eta_c if maturity == "consolidated" else eta


def compute_modulator(
    f: int,
    *,
    q_teacher: float,
    gamma_bf: float,
    b_bar: float,
    kappa: float,
    terms: tuple[str, ...],
) -> float:
    """m_t = q_T · (1 + κ·γ_BF) · (f − b̄), restricted to the enabled modulator terms.

    ``f`` must be exactly ±1 (the only teaching signal). Without ``reliability`` q_T is 1;
    without ``surprise`` γ_BF is 0. ``novelty`` never enters the magnitude (spec §5).
    """
    if f not in (-1, 1):
        raise ValueError(f"teaching signal must be +1 or -1, got {f!r}")
    if "teacher" not in terms:
        raise ValueError("modulator without 'teacher' is incoherent")
    if not 0.0 <= q_teacher <= 1.0:
        raise ValueError("teacher reliability q must be in [0, 1]")
    if gamma_bf < 0.0:
        raise ValueError("Bayes-factor surprise must be >= 0")
    q = q_teacher if "reliability" in terms else 1.0
    gamma = gamma_bf if "surprise" in terms else 0.0
    return q * (1.0 + kappa * gamma) * (f - b_bar)


class RunningBaseline:
    """b̄: running mean of the ±1 judgement f, keyed according to the ``centering`` switch.

    * ``none``                  — b̄ ≡ 0 (uncentred; the v1 rule of card 03)
    * ``per_context``           — one mean per context key
    * ``per_proposition_type``  — one mean per proposition type (never per teacher verdict)

    Modulator-side state: it feeds m_t (L2) and is not a learned parameter θ.
    """

    def __init__(self, mode: str, rate: float = 0.05) -> None:
        if mode not in ("none", "per_context", "per_proposition_type"):
            raise ValueError(f"unknown centering {mode!r}")
        self.mode, self.rate = mode, rate
        self._stats: dict[Any, tuple[float, int]] = {}

    def _key(self, context: Any, ptype: Any) -> Any:
        return context if self.mode == "per_context" else ptype

    def value(self, *, context: Any = None, ptype: Any = None) -> float:
        if self.mode == "none":
            return 0.0
        return self._stats.get(self._key(context, ptype), (0.0, 0))[0]

    def observe(self, f: int, *, context: Any = None, ptype: Any = None) -> None:
        if f not in (-1, 1):
            raise ValueError(f"teaching signal must be +1 or -1, got {f!r}")
        if self.mode == "none":
            return
        key = self._key(context, ptype)
        mean, n = self._stats.get(key, (0.0, 0))
        n += 1
        self._stats[key] = (mean + max(1.0 / n, self.rate) * (f - mean), n)


@dataclass(frozen=True)
class Updaters:
    """The update functions selected by one config (switch → function), plus their constants."""

    feedback: str
    trace_tau: int
    store: str
    normalization: str
    eta: float
    eta_phi: float
    eta_c: float
    weight_cap: float
    bcm_rate: float
    bcm_tau: float
    unit: Callable[..., Any]
    normalize: Callable[..., Any]

    @property
    def uses_trace(self) -> bool:
        """Eligibility traces are needed only when the feedback does not name the proposition."""
        return self.feedback == "bare"

    def trace_delta(self, u_pre: Any, u_post: Any, e_theta: Any) -> Any:
        return update_trace(u_pre, u_post, e_theta, tau=float(self.trace_tau))

    def edge_delta(
        self, *, m_t: Any, e_theta: Any = None, tag: Any = None, eta: float | None = None
    ) -> Any:
        eta = self.eta if eta is None else eta
        if self.feedback == "named":
            if tag is None:
                raise ValueError("feedback=named needs the selection tag of the judged path")
            return update_edge_named(m_t, tag, eta=eta)
        if e_theta is None:
            raise ValueError("feedback=bare needs the edge eligibility trace")
        return update_edge_bare(e_theta, m_t, eta=eta)

    def normalize_delta(
        self, theta: Any, *, u_pre: Any = None, u_post: Any = None, e_theta: Any = None
    ) -> Any:
        """Δθ of the normalisation step. ``theta`` is a source unit's outgoing weights (last axis)
        for heterosynaptic; BCM needs the post activity and the threshold in ``e_theta``."""
        if self.normalization == "bcm":
            if u_pre is None or u_post is None or e_theta is None:
                raise ValueError("normalization=bcm needs u_pre, u_post and the threshold e_theta")
            return update_normalize_bcm(u_pre, u_post, e_theta, rate=self.bcm_rate)
        if self.normalization == "heterosynaptic":
            return update_normalize_heterosynaptic(theta, cap=self.weight_cap)
        return update_normalize_none(theta)

    def bcm_threshold_delta(self, u_post: Any, threshold: Any) -> Any:
        return update_bcm_threshold(u_post, threshold, tau=self.bcm_tau)

    def unit_delta(self, x: Any, theta: Any, m_t: Any, *, eta: float | None = None) -> Any:
        if self.store == "episodic":
            return update_unit_episodic(x, theta, m_t)
        return update_prototype_stats(x, theta, m_t, eta=self.eta_phi if eta is None else eta)


def select_updaters(cfg: SNIConfig) -> Updaters:
    """Map every plasticity switch of ``cfg`` onto its update function."""
    p = cfg.params
    return Updaters(
        feedback=cfg.feedback,
        trace_tau=cfg.trace_tau,
        store=cfg.store,
        normalization=cfg.normalization,
        eta=p.eta,
        eta_phi=p.eta_phi,
        eta_c=p.eta_c,
        weight_cap=p.weight_cap,
        bcm_rate=p.bcm_rate,
        bcm_tau=p.bcm_tau,
        unit=update_unit_episodic if cfg.store == "episodic" else update_prototype_stats,
        normalize={
            "none": update_normalize_none,
            "heterosynaptic": update_normalize_heterosynaptic,
            "bcm": update_normalize_bcm,
        }[cfg.normalization],
    )


def make_baseline(cfg: SNIConfig) -> RunningBaseline:
    return RunningBaseline(cfg.centering, cfg.params.baseline_rate)

teachers/adversarial.py:
"""adversarial(fraction): a teacher that is *consistently* wrong about a fixed fraction of the
facts — for each selected (subject, relation) it holds one fixed wrong word, answers with it and
judges by it. Consistency is what makes it dangerous: unlike noise, its lies do not average out,
and only multi-teacher maturity (k distinct teachers) and gold tasks can expose them."""

from __future__ import annotations

import zlib
from typing import Hashable

from sni.teaching import Act
from teachers.base import Teacher, World


class AdversarialTeacher(Teacher):
    def __init__(
        self, world: World, fraction: float, name: str | None = None, seed: int = 0
    ) -> None:
        if not 0.0 <= fraction <= 1.0:
            raise ValueError("fraction must be in [0, 1]")
        super().__init__(world, name or f"adversarial{fraction:g}", seed)
        self.fraction, self.seed = float(fraction), int(seed)

    def _h(self, *parts: object) -> int:
        return zlib.crc32(repr((self.seed, self.name) + parts).encode())

    def lies_about(self, subject: Hashable, relation: str) -> bool:
        return (self._h(subject, relation) % 10_000) / 10_000.0 < self.fraction

    def _lie(self, subject: Hashable, relation: str, truth: str | None) -> str | None:
        pool = sorted(w for w in self.world.vocabulary(relation) if w != truth)
        return pool[self._h("lie", subject, relation) % len(pool)] if pool else truth

    def holds(self, item: Hashable, act: Act) -> str | None:
        about = act.meta.get("about")
        subject: Hashable | None = item if about is None else about
        for r in act.meta.get("path", ()):
            if subject is None:
                return None
            truth = self.world.relate(subject, r)
            subject = self._lie(subject, r, truth) if self.lies_about(subject, r) else truth
        return None if subject is None else str(subject)

teachers/base.py:
"""Simulated teachers (spec §6): they answer the brain's questions and judge its acts ±1.

A teacher only ever sees a *world* (the testbed's ground truth, harness side) and the brain's
act. It never writes into the brain: the harness passes its word to ``learner.hear`` (only after
the brain asked) and its ±1 to ``learner.feedback``.

World protocol (implemented by every testbed)::

    relate(subject, relation) -> str | None   # ground truth: item/word --relation--> word
    classify(raw) -> item | None              # which item a raw input shows (to judge SHOW)
    example(word, rng) -> (item, raw) | None  # an instance of a word (to answer "show me one")
    vocabulary(relation) -> list[str]         # the words a relation can point to

``subject`` is either a testbed *item* (an input the brain sees) or a *word*. An act's
``meta["about"]`` is ``None`` when the act is about the input itself, otherwise the word the
brain asked about; ``meta["path"]`` is the relation path still to follow.
"""

from __future__ import annotations

import zlib
from typing import Any, Hashable, Protocol

import numpy as np

from sni.frames import FRAMES
from sni.teaching import Act


class World(Protocol):
    def relate(self, subject: Hashable, relation: str) -> str | None: ...
    def classify(self, raw: Any) -> Hashable | None: ...
    def example(self, word: str, rng: np.random.Generator) -> tuple[Hashable, Any] | None: ...
    def vocabulary(self, relation: str) -> list[str]: ...


def follow(world: World, subject: Hashable | None, path: tuple[str, ...]) -> str | None:
    """Walk ``path`` from ``subject`` through the world's ground truth."""
    for r in path:
        if subject is None:
            return None
        subject = world.relate(subject, r)
    return None if subject is None else str(subject)


def true_answer(world: World, item: Hashable, act: Act) -> str | None:
    """The answer a perfectly reliable teacher holds true for ``act`` (or for the question)."""
    about = act.meta.get("about")
    return follow(world, item if about is None else about, tuple(act.meta.get("path", ())))


def is_correct(world: World, item: Hashable, act: Act) -> bool:
    """Seed verdict on an act: is the proposed answer true in the world?"""
    frame = FRAMES.get(act.frame)
    if act.kind not in ("answer", "confirm", "proposal"):
        return False
    if frame is not None and frame.reverse and act.kind != "proposal":
        shown = act.meta.get("shown_raw")
        if shown is None:
            return False
        return world.relate(world.classify(np.asarray(shown)), "named") == act.meta.get("about")
    return act.answer is not None and act.answer == true_answer(world, item, act)


class Teacher:
    """The seed teacher (q = 1): answers truly, judges truly."""

    def __init__(self, world: World, name: str = "seed", seed: int = 0) -> None:
        self.world, self.name = world, name
        self.rng = np.random.default_rng(np.random.SeedSequence([seed, zlib.crc32(name.encode())]))

    def holds(self, item: Hashable, act: Act) -> str | None:
        """What this teacher believes the answer is (seed: the truth)."""
        return true_answer(self.world, item, act)

    def answer(self, item: Hashable, act: Act) -> str | None:
        """The word this teacher gives to the brain's question ``act`` (kind ``ask``)."""
        return self.holds(item, act)

    def judge(self, item: Hashable, act: Act) -> int:
        frame = FRAMES.get(act.frame)
        if frame is not None and frame.reverse and act.kind != "proposal":
            return 1 if is_correct(self.world, item, act) else -1
        return 1 if act.answer is not None and act.answer == self.holds(item, act) else -1


SeedTeacher = Teacher


def _other(words: list[str], truth: str | None, rng: np.random.Generator) -> str | None:
    pool = [w for w in words if w != truth]
    return pool[int(rng.integers(len(pool)))] if pool else truth

teachers/gold.py:
"""Gold tasks (spec §6): 1 in ``every`` interactions is a probe whose seed verdict the harness
knows. The teacher's verdict is compared with it and the brain is told only *whether that
teacher agreed* (``learner.observe_gold``), which moves the teacher's reliability q_T and
nothing else. A gold interaction gives no ±1 feedback to memory."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class GoldSchedule:
    every: int = 6
    offset: int = 5

    def __post_init__(self) -> None:
        if self.every < 2:
            raise ValueError("gold tasks must leave room for teaching (every >= 2)")

    def is_gold(self, step: int) -> bool:
        return step % self.every == self.offset % self.every

teachers/noisy.py:
"""noisy(p): an honest but unreliable teacher. Each judgement is flipped with probability p, and
each answer to a question is replaced by a random wrong word with probability p. Errors are
independent across trials (expected uncertainty, card 08 block B)."""

from __future__ import annotations

from typing import Hashable

from sni.teaching import Act
from teachers.base import Teacher, World, _other


class NoisyTeacher(Teacher):
    def __init__(self, world: World, p: float, name: str | None = None, seed: int = 0) -> None:
        if not 0.0 <= p <= 1.0:
            raise ValueError("p must be a probability")
        super().__init__(world, name or f"noisy{p:g}", seed)
        self.p = float(p)

    def answer(self, item: Hashable, act: Act) -> str | None:
        truth = self.holds(item, act)
        if self.rng.random() < self.p:
            rel = act.meta.get("path", ("named",))[-1]
            return _other(self.world.vocabulary(rel), truth, self.rng)
        return truth

    def judge(self, item: Hashable, act: Act) -> int:
        f = super().judge(item, act)
        return -f if self.rng.random() < self.p else f


__all__ = ["NoisyTeacher"]

lab/wordworld.py:
"""Word world for the SNI Live Lab (a TB-4b prototype): words perceived through frozen GloVe-100
vectors, a 17-category taxonomy and category-level facts. Implements the harness ``World``
protocol (``relate``, ``classify``, ``example``, ``vocabulary``) so the shared teaching loop, the
seed teacher and every baseline run on it unchanged.

Perception only: the vectors never change and never see a label. Everything the brain knows about
a word's kind, and every fact, is learned inside ``sni/`` from ±1 judgements.
"""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import Any, Hashable

import numpy as np
import yaml

from sni.frames import FRAMES, Frame

DATA = Path(__file__).parent / "data"
DIM = 100

# One extra frame for the lab: a percept read along named → is-a → is-a (e.g. tiger → mammal →
# animal → organism needs three hops; this frame reads the first two relations after naming).
FRAMES.setdefault("IS-A-2", Frame("IS-A-2", ("named", "is-a", "is-a")))

LAB_FRAMES = (
    "WHAT-IS", "IS-A", "IS-A-2", "HAS", "LIVES-IN",
    "IS-A/word", "HAS/word", "LIVES-IN/word",
)  # fmt: skip

REL_KEYS = {"is-a": "is_a", "has": "has", "lives-in": "lives_in"}


class Vectors:
    """The frozen, int8-quantised GloVe table (same bytes the browser loads)."""

    def __init__(self, root: Path = DATA) -> None:
        self.words: list[str] = json.loads((root / "glove100.vocab.json").read_text())
        q = np.frombuffer((root / "glove100.i8").read_bytes(), dtype=np.int8)
        s = np.frombuffer((root / "glove100.scale.f32").read_bytes(), dtype="<f4")
        self.X = q.reshape(len(self.words), DIM).astype(np.float64) * s[:, None]
        self.index = {w: i for i, w in enumerate(self.words)}

    def __contains__(self, w: str) -> bool:
        return w in self.index

    def get(self, w: str) -> np.ndarray:
        return self.X[self.index[w]].copy()


@lru_cache(maxsize=1)
def vectors() -> Vectors:
    return Vectors()


def load_spec(root: Path = DATA) -> dict[str, Any]:
    return yaml.safe_load((root / "world.yaml").read_text())


class WordWorld:
    """Ground truth for the seed teacher and the metrics. The brain never reads it."""

    def __init__(self, seed: int = 0, *, n_train: int = 10, vec: Vectors | None = None) -> None:
        self.vec = vec or vectors()
        spec = load_spec()
        self.cats: dict[str, list[str]] = {c: list(ws) for c, ws in spec["categories"].items()}
        self.categories = list(self.cats)
        self.facts: dict[str, dict[str, str]] = {
            r: dict(spec.get(k, {}) or {}) for r, k in REL_KEYS.items()
        }
        self.kind = {w: c for c, ws in self.cats.items() for w in ws}
        rng = np.random.default_rng(np.random.SeedSequence([seed, 0x5EED]))
        self.train: dict[str, list[str]] = {}
        self.test: dict[str, list[str]] = {}
        for c, ws in self.cats.items():
            p = list(rng.permutation(ws))
            self.train[c], self.test[c] = p[:n_train], p[n_train:]
        self.rng = rng
        world_words = set(self.kind)
        self._warm = [w for w in self.vec.words[:5000] if w not in world_words]
        self._by_vec = {self.vec.get(w).tobytes(): w for w in world_words}

    # --- World protocol ------------------------------------------------------------------------
    def relate(self, subject: Hashable, relation: str) -> str | None:
        s = str(subject)
        if relation == "named":
            return self.kind.get(s)
        return self.facts.get(relation, {}).get(s)

    def classify(self, raw: Any) -> Hashable | None:
        return self._by_vec.get(np.asarray(raw, dtype=np.float64).tobytes())

    def example(self, word: str, rng: np.random.Generator) -> tuple[Hashable, Any] | None:
        pool = self.train.get(word)
        if not pool:
            return None
        w = str(pool[int(rng.integers(len(pool)))])
        return w, self.vec.get(w)

    def vocabulary(self, relation: str) -> list[str]:
        if relation == "named":
            return list(self.categories)
        return sorted(set(self.facts.get(relation, {}).values()))

    # --- streams -------------------------------------------------------------------------------
    def warmup_stream(self, n: int) -> list[np.ndarray]:
        """Unlabelled everyday words (never world words) for the encoder's centring warm-up."""
        idx = self.rng.choice(len(self._warm), size=n, replace=False)
        return [self.vec.get(self._warm[i]) for i in idx]

    def items(self, cats: list[str], split: str = "train") -> list[tuple[str, np.ndarray]]:
        src = self.train if split == "train" else self.test
        return [(w, self.vec.get(w)) for c in cats for w in src[c]]
